// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 wei);
        vm.prank(alice);
        c.deposit{value: 1 wei}();
        uint256 aliceBalanceBeforeRefund = alice.balance;
        vm.prank(alice);
        c.refund();
        uint256 aliceBalanceAfterRefund = alice.balance;
        assertTrue(aliceBalanceAfterRefund == aliceBalanceBeforeRefund + 1 wei);
    }
}
